uv run python -c 'from pathlib import Path
root = Path(".")
assert not (root / "docs/assets/retornatus-mascot.webp").exists()
targets = [Path("README.md"), Path("CHANGELOG.md"), Path("pyproject.toml")]
manifest = Path("MANIFEST.in")
if manifest.exists():
    targets.append(manifest)
for folder in (Path("docs"), Path("scripts"), Path("tests")):
    targets.extend(p for p in folder.rglob("*") if p.is_file())
targets.extend(Path(".").glob("*.html"))
hits = []
for path in targets:
    if path.name == "retornatus-mascot.webp":
        hits.append(str(path))
        continue
    if path.suffix.lower() in {".webp", ".png", ".jpg", ".jpeg", ".gif"}:
        continue
    try:
        body = path.read_text(encoding="utf-8")
    except (UnicodeDecodeError, OSError):
        continue
    if "retornatus-mascot.webp" in body:
        hits.append(str(path))
assert hits == [], hits
print("old mascot absent")'

